import { test, expect } from "@playwright/test";

const seededDocument = {
  id: "playwright-doc",
  title: "Playwright Smoke.md",
  body: "# Playwright Smoke\n\nThis document stabilizes the shell for smoke coverage.",
  createdAt: "2026-03-10T00:00:00.000Z",
};

test.beforeEach(async ({ page }) => {
  await page.addInitScript((documentState) => {
    window.localStorage.setItem("files", JSON.stringify([documentState]));
    window.localStorage.setItem("currentDocument", JSON.stringify(documentState));
    window.localStorage.setItem(
      "profileV3",
      JSON.stringify({
        enableAutoSave: true,
        enableWordsCount: true,
        enableCharactersCount: true,
        enableScrollSync: true,
        tabSize: 4,
        keybindings: "default",
        enableNightMode: false,
        enableGitHubComment: true,
      })
    );
  }, seededDocument);
});

test("loads the editor shell and core controls", async ({ page }) => {
  await page.goto("/");

  await expect(
    page.getByRole("heading", { level: 2, name: seededDocument.title })
  ).toBeVisible();
  await expect(page.getByRole("button", { name: "Toggle sidebar" })).toBeVisible();
  await expect(page.locator("#preview")).toBeVisible();
  await expect(page.getByTestId("word-count")).toContainText("11 words");
  await expect(page.getByTestId("character-count")).toContainText("74 characters");

  await page.getByRole("button", { name: "Hide preview" }).click();
  await expect(page.locator("#preview")).toHaveCount(0);
  await expect(page.getByRole("button", { name: "Show preview" })).toBeVisible();

  await page.getByRole("button", { name: "Open settings" }).click();
  await expect(page.getByRole("dialog", { name: "Settings" })).toBeVisible();
  await expect(page.getByRole("switch", { name: "Night Mode" })).toBeVisible();
});

import { expect } from "chai";
import fs, { PathLike } from "fs";
import sinon from "sinon";
import * as vscode from "vscode";

import {Coverage} from "../../src/coverage-system/coverage";
import {Config} from "../../src/extension/config";

const stubConfig = sinon.createStubInstance(Config) as Config;

suite("Coverage Tests", () => {
    teardown(() => sinon.restore());

    test("Constructor should setup properly @unit", () => {
        expect(() => {
            new Coverage(stubConfig);
        }).not.to.throw();
    });

    test("#load: Should reject when readFile returns an error @unit", async () => {
        sinon.stub(fs, "readFile").callsFake(() => {
            throw new Error("could not read from fs");
        });

        const coverage = new Coverage(
            stubConfig,
        );

        try {
            await coverage.load("pathtofile");
        } catch (e: any) {
            expect(e.message).to.equal("could not read from fs");
        }
    });

    test("#load: Should return a data string @unit", async () => {
        const stubReadFile = sinon.stub(fs, "readFile").callsFake(
            (_: number | PathLike, cb: (err: NodeJS.ErrnoException | null, data: Buffer<ArrayBuffer>) => void) => {
                return cb(undefined as any, Buffer.from("lcovhere"));
            },
        );

        const coverage = new Coverage(
            stubConfig,
        );

        const path = "pathtofile";
        const dataString = await coverage.load(path);
        expect(dataString).to.equal("lcovhere");
        expect(stubReadFile.calledWith(path));
    });

    test("#pickFile: Should return undefined if no item is picked @unit", async () => {

        sinon.stub(vscode.window, "showQuickPick").resolves(undefined);
        const stubWarningMessage = sinon.stub(vscode.window, "showWarningMessage");

        const coverage = new Coverage(
            stubConfig,
        );

        await coverage.pickFile(["test1", "test2"], "nope");
        expect(stubWarningMessage.calledWith("Did not choose a file!"));
    });

    test("#pickFile: Should return vscode.uri if filePaths is a string @unit", async () => {
        const coverage = new Coverage(
            stubConfig,
        );

        const value = await coverage.pickFile("123", "nope");

        expect(value?.path).to.equal("/123");
    });

    test("#pickFile: Should return vscode.uri if filePaths is an array with one value @unit", async () => {
        const coverage = new Coverage(
            stubConfig,
        );

        const value = await coverage.pickFile(["123"], "nope");
        expect(value?.path).to.equal("/123");
    });
});

import { expect } from "chai";
import sinon from "sinon";
import { FileSystemWatcher, OutputChannel, workspace } from "vscode";

import { CoverageService } from "../../src/coverage-system/coverageservice";
import { StatusBarToggler } from "../../src/extension/statusbartoggler";

const mockOutputChannel = {appendLine: (x) => {}} as OutputChannel;
const mockFileWatcher = {
    dispose: () => {},
    onDidChange: (fn: any) => {},
    onDidCreate: (fn: any) => {},
    onDidDelete: (fn: any) => {},
};
const mockStatusBarToggler = {setLoading: () => {}} as StatusBarToggler;

suite("CoverageService Tests", function() {
    teardown(() => sinon.restore());

    test("Should listen for all paths specified in manualCoverageFilePaths @unit", () => {
        const config: any = {
            manualCoverageFilePaths: [
                "/path1",
                "/path2",
            ],
        };
        const service = new CoverageService(config, mockOutputChannel, mockStatusBarToggler);

        const stubCreateFileSystemWatcher = sinon.stub(workspace, "createFileSystemWatcher")
            .returns(mockFileWatcher as FileSystemWatcher);

        (service as any).listenToFileSystem();

        expect(stubCreateFileSystemWatcher.calledWith("{/path1,/path2}"));
    });

    test("Should listen for coverage file names in workspace @unit", () => {
        const config: any = {
            coverageBaseDir: "custom/path/*",
            coverageFileNames: [
                "coverage.xml",
                "custom-lcov.info",
            ],
            manualCoverageFilePaths: [],
        };
        const service = new CoverageService(config, mockOutputChannel, mockStatusBarToggler);

        const stubCreateFileSystemWatcher = sinon.stub(workspace, "createFileSystemWatcher")
            .returns(mockFileWatcher as FileSystemWatcher);

        (service as any).listenToFileSystem();

        let prefix = config.coverageBaseDir;
        if (workspace.workspaceFolders) {
            const workspaceFolders = workspace.workspaceFolders.map((wf) => wf.uri.fsPath);
            prefix = `{${workspaceFolders}}/${prefix}`;
        }
        expect(stubCreateFileSystemWatcher.calledWith(`${prefix}/{coverage.xml,custom-lcov.info}`));
    });
});

import { expect } from "chai";
import { Section } from "lcov-parse";
import sinon from "sinon";
import { DecorationOptions, Range, TextEditor, TextEditorDecorationType } from "vscode";
import { Renderer } from "../../src/coverage-system/renderer";
import { SectionFinder } from "../../src/coverage-system/sectionfinder";
import { Config } from "../../src/extension/config";

const stubConfig = sinon.createStubInstance(Config) as Config;

suite("Renderer Tests", function() {
    test("Constructor should setup properly @unit", function(done) {
        const sectionFinder: SectionFinder = {} as SectionFinder;
        expect(() => new Renderer(stubConfig, sectionFinder)).not.to.throw();
        return done();
    });

    test("renderCoverage should not error with empty map and empty TextEditor array @unit", function(done) {
        const sectionFinder: SectionFinder = {} as SectionFinder;
        const renderer: Renderer = new Renderer(stubConfig, sectionFinder);

        renderer.renderCoverage(new Map<string, Section>(), new Array<TextEditor>());
        return done();
    });

    test("renderCoverage should not error with empty map and single textEditor @unit", function(done) {
        const sections: Section[] = [{} as Section];
        const sectionFinder: SectionFinder = {
            findSectionsForEditor: (
                functionTextEditor: TextEditor,
                functionSections: Map<string, Section>,
            ): Section[] => {
                expect(functionTextEditor).not.to.equal(null);
                expect(functionSections).not.to.equal(null);
                return sections;
            },
        } as SectionFinder;
        const renderer: Renderer = new Renderer(stubConfig, sectionFinder);
        const textEditor: TextEditor = {} as TextEditor;

        textEditor.setDecorations = function(
            decorationType: TextEditorDecorationType,
            rangesOrOptions: Range[] | DecorationOptions[],
        ): void {
            const configArray = [
                stubConfig.fullCoverageDecorationType,
                stubConfig.noCoverageDecorationType,
                stubConfig.partialCoverageDecorationType,
            ];
            expect(configArray).to.include(decorationType);
            expect(rangesOrOptions).to.deep.equal([]);
        };
        const textEditorArray: TextEditor[] = new Array<TextEditor>();
        textEditorArray.push(textEditor);
        renderer.renderCoverage(new Map<string, Section>(), textEditorArray);
        return done();
    });

    test("removeDecorationsForEditor should not error @unit", function(done) {
        const sectionFinder: SectionFinder = {} as SectionFinder;
        const renderer: Renderer = new Renderer(stubConfig, sectionFinder);
        const textEditor: TextEditor = {} as TextEditor;

        textEditor.setDecorations = function(
            decorationType: TextEditorDecorationType,
            rangesOrOptions: Range[] | DecorationOptions[],
        ): void {
            const configArray = [
                stubConfig.fullCoverageDecorationType,
                stubConfig.noCoverageDecorationType,
                stubConfig.partialCoverageDecorationType,
            ];
            expect(configArray).to.include(decorationType);
            expect(rangesOrOptions).to.deep.equal([]);
        };
        renderer.removeDecorationsForEditor(textEditor);
        return done();
    });
});
